-- VIEW: stock_analysis.vw_analysis_result_summary_80d
-- Generated by scripts/db/export_postgres_ddl.py

SET search_path = "stock_analysis", pg_catalog;

CREATE OR REPLACE VIEW "stock_analysis"."vw_analysis_result_summary_80d" AS
 SELECT analysis_result_id,
    hypothesis_name,
    count(*) AS sample_count,
    sum(
        CASE
            WHEN return_80d_pct > 0::numeric THEN 1
            ELSE 0
        END) AS win_count_80d,
    sum(
        CASE
            WHEN return_80d_pct < 0::numeric THEN 1
            ELSE 0
        END) AS lose_count_80d,
    sum(
        CASE
            WHEN return_80d_pct = 0::numeric THEN 1
            ELSE 0
        END) AS draw_count_80d,
    round(sum(
        CASE
            WHEN return_80d_pct > 0::numeric THEN 1
            ELSE 0
        END)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 4) AS win_rate_80d_pct,
    round(sum(
        CASE
            WHEN return_80d_pct < 0::numeric THEN 1
            ELSE 0
        END)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 4) AS lose_rate_80d_pct,
    round(avg(return_80d_pct), 4) AS avg_return_80d_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (return_80d_pct::double precision))::numeric, 4) AS median_return_80d_pct,
    round(percentile_cont(0.10::double precision) WITHIN GROUP (ORDER BY (return_80d_pct::double precision))::numeric, 4) AS p10_return_80d_pct,
    round(percentile_cont(0.25::double precision) WITHIN GROUP (ORDER BY (return_80d_pct::double precision))::numeric, 4) AS p25_return_80d_pct,
    round(percentile_cont(0.75::double precision) WITHIN GROUP (ORDER BY (return_80d_pct::double precision))::numeric, 4) AS p75_return_80d_pct,
    round(percentile_cont(0.90::double precision) WITHIN GROUP (ORDER BY (return_80d_pct::double precision))::numeric, 4) AS p90_return_80d_pct,
    min(return_80d_pct) AS min_return_80d_pct,
    max(return_80d_pct) AS max_return_80d_pct,
    count(DISTINCT ticker) AS ticker_count,
    count(DISTINCT trade_date) AS signal_date_count
   FROM analysis_result_detail ard
  WHERE return_80d_pct IS NOT NULL
  GROUP BY analysis_result_id, hypothesis_name;
